export const SEGY_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/segy-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getSegyStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(SEGY_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
